export type Edition = "free" | "pro";

export type CatalogCategory =
  | "Interaction"
  | "Inputs"
  | "Cards"
  | "Feedback"
  | "Effects"
  | "Backgrounds"
  | "Hooks";

export type CatalogEntry = {
  name: string;
  href: string;
  category: CatalogCategory;
  edition: Edition;
  /** Preview image in /public, shown when hovering the row. */
  image?: string;
};

export const CATALOG_CATEGORIES: CatalogCategory[] = [
  "Interaction",
  "Inputs",
  "Cards",
  "Feedback",
  "Effects",
  "Backgrounds",
  "Hooks",
];

// Preview images in /public/images are generated by `npm run previews`.
const component = (
  name: string,
  slug: string,
  category: CatalogCategory
): CatalogEntry => ({
  name,
  href: `/components/${slug}`,
  category,
  edition: "free",
  image: `/images/${slug}.png`,
});

const background = (name: string, slug: string): CatalogEntry => ({
  name,
  href: `/components/backgrounds/${slug}`,
  category: "Backgrounds",
  edition: "free",
  image: `/images/${slug}.png`,
});

const hook = (name: string, slug: string): CatalogEntry => ({
  name,
  href: `/utilities/${slug}`,
  category: "Hooks",
  edition: "free",
  image: `/images/${slug}.png`,
});

